import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    df_counted = df[df['row_kind'] == 'counted'].copy()
except Exception:
    df_counted = df.copy()

try:
    metrics = ['earned_premium', 'claim_count', 'claim_amount']
    eda = {}
    for col in metrics:
        s = df_counted[col].dropna()
        eda[col] = {
            "mean": float(s.mean()),
            "std": float(s.std()),
            "min": float(s.min()),
            "max": float(s.max()),
            "median": float(s.median()),
            "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception:
    pass

try:
    import numpy as np
    numeric_cols = ['earned_premium', 'claim_count', 'claim_amount']
    corr_dict = {}
    for i, c1 in enumerate(numeric_cols):
        for c2 in numeric_cols[i+1:]:
            pair = df_counted[[c1, c2]].dropna()
            if len(pair) > 1:
                r = float(pair[c1].corr(pair[c2]))
                if abs(r) >= 0.2:
                    corr_dict[f"{c1}__{c2}"] = round(r, 4)
    result['correlations'] = corr_dict
except Exception:
    pass

try:
    import numpy as np
    segs = []
    segment_cols = ['line', 'region']
    metric_cols = ['earned_premium', 'claim_count', 'claim_amount']
    for seg_col in segment_cols:
        for met_col in metric_cols:
            grp = df_counted.groupby(seg_col)[met_col].sum().reset_index()
            grp = grp.sort_values(met_col, ascending=False).head(10)
            segs.append({
                "segment_column": seg_col,
                "metric_column": met_col,
                "aggregation": "sum",
                "label": None,
                "results": [{"name": str(r[seg_col]), "value": float(r[met_col])} for _, r in grp.iterrows()]
            })
    ep_total = df_counted['earned_premium'].sum()
    ca_total = df_counted['claim_amount'].sum()
    overall_lr = float(ca_total / ep_total) if ep_total > 0 else 0.0
    segs.append({
        "segment_column": "line",
        "metric_column": "claim_amount",
        "aggregation": "ratio",
        "label": "loss_ratio",
        "results": [
            {"name": str(row['line']),
             "value": float(row['claim_amount'] / row['earned_premium']) if row['earned_premium'] > 0 else 0.0}
            for _, row in df_counted.groupby('line')[['earned_premium','claim_amount']].sum().reset_index().iterrows()
        ]
    })
    segs.append({
        "segment_column": "region",
        "metric_column": "claim_amount",
        "aggregation": "ratio",
        "label": "loss_ratio",
        "results": [
            {"name": str(row['region']),
             "value": float(row['claim_amount'] / row['earned_premium']) if row['earned_premium'] > 0 else 0.0}
            for _, row in df_counted.groupby('region')[['earned_premium','claim_amount']].sum().reset_index().iterrows()
        ]
    })
    result['segments'] = segs
except Exception:
    pass

try:
    import numpy as np
    df_counted['month_dt'] = pd.to_datetime(df_counted['month'])
    df_counted['ym'] = df_counted['month_dt'].dt.to_period('M')
    monthly = df_counted.groupby('ym')[['earned_premium','claim_count','claim_amount']].sum().sort_index()
    trends = []
    for col in ['earned_premium', 'claim_count', 'claim_amount']:
        if len(monthly) >= 2:
            vals = monthly[col]
            first_val = float(vals.iloc[0])
            last_val = float(vals.iloc[-1])
            pct = float((last_val - first_val) / first_val * 100) if first_val != 0 else 0.0
            direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
            trends.append({"column": col, "period": "MoM", "direction": direction, "pct_change": round(pct, 4), "segment": None})
    result['trends'] = trends
except Exception:
    pass

try:
    import numpy as np
    from scipy import stats as sp_stats
    anomalies = []
    skip_cols = set()
    for col in ['earned_premium', 'claim_count', 'claim_amount']:
        s = df_counted[col].dropna()
        if s.nunique() < 5:
            skip_cols.add(col)
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -float(s.min()) if float(s.min()) < 0 else 0
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo_t = q1 - 3 * iqr
        hi_t = q3 + 3 * iqr
        mask = (s_t < lo_t) | (s_t > hi_t)
        flagged_frac = mask.sum() / len(s_t)
        if flagged_frac > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": "heavy-tailed distribution",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme values are natural for this distribution"
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_t) - shift)
            hi_orig = float(np.expm1(hi_t) - shift)
        else:
            lo_orig = float(lo_t)
            hi_orig = float(hi_t)
        flagged_idx = s_t[mask].index.tolist()
        lo5_t = q1 - 5 * iqr
        hi5_t = q3 + 5 * iqr
        lo4_t = q1 - 4 * iqr
        hi4_t = q3 + 4 * iqr
        for idx in flagged_idx:
            if len(anomalies) >= 25:
                break
            raw_val = float(df_counted.loc[idx, col])
            tv = float(s_t.loc[idx])
            if tv > hi5_t or tv < lo5_t:
                sev = "critical"
            elif tv > hi4_t or tv < lo4_t:
                sev = "high"
            else:
                sev = "medium"
            exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
            anomalies.append({
                "column": col,
                "row_index": int(idx),
                "value": raw_val,
                "expected_range": exp_range,
                "severity": sev,
                "explanation": f"{col} value {raw_val} lies outside expected range {exp_range}"
            })
    result['anomalies'] = anomalies
except Exception:
    pass

try:
    import numpy as np
    df_counted['month_dt'] = pd.to_datetime(df_counted['month'])
    df_counted['ym'] = df_counted['month_dt'].dt.to_period('M')
    monthly_ep = df_counted.groupby('ym')['earned_premium'].sum().sort_index()
    if len(monthly_ep) >= 3:
        x = np.arange(len(monthly_ep))
        y = monthly_ep.values.astype(float)
        coeffs = np.polyfit(x, y, 1)
        forecast_pts = []
        last_period = monthly_ep.index[-1]
        for i in range(1, 4):
            next_period = last_period + i
            pred = float(np.polyval(coeffs, len(monthly_ep) - 1 + i))
            forecast_pts.append({"period": str(next_period), "value": round(pred, 2)})
        result['forecast_points'] = forecast_pts
except Exception:
    pass

result['assumptions'] = [
    "Only rows with row_kind == 'counted' are used for all metrics.",
    "Loss ratio = sum(claim_amount) / sum(earned_premium) per segment (ratio of sums).",
    "Trend direction: >1% change = up/down, else flat; MoM compares first vs last monthly total.",
    "Anomaly detection uses 3×IQR extreme boundary; log1p applied when |skew| > 2.",
    "Forecast is a simple linear extrapolation of monthly earned_premium totals (3 periods)."
]

