try:
    import numpy as np
    from scipy import stats as sp_stats
    anomalies = []
    skip_cols = set()
    for col in ['earned_premium', 'claim_count', 'claim_amount']:
        s = df_counted[col].dropna()
        if s.nunique() < 5:
            skip_cols.add(col)
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -float(s.min()) if float(s.min()) < 0 else 0
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo_t = q1 - 3 * iqr
        hi_t = q3 + 3 * iqr
        mask = (s_t < lo_t) | (s_t > hi_t)
        flagged_frac = mask.sum() / len(s_t)
        if flagged_frac > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": "heavy-tailed distribution",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme values are natural for this distribution"
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_t) - shift)
            hi_orig = float(np.expm1(hi_t) - shift)
        else:
            lo_orig = float(lo_t)
            hi_orig = float(hi_t)
        flagged_idx = s_t[mask].index.tolist()
        lo5_t = q1 - 5 * iqr
        hi5_t = q3 + 5 * iqr
        lo4_t = q1 - 4 * iqr
        hi4_t = q3 + 4 * iqr
        for idx in flagged_idx:
            if len(anomalies) >= 25:
                break
            raw_val = float(df_counted.loc[idx, col])
            tv = float(s_t.loc[idx])
            if tv > hi5_t or tv < lo5_t:
                sev = "critical"
            elif tv > hi4_t or tv < lo4_t:
                sev = "high"
            else:
                sev = "medium"
            exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
            anomalies.append({
                "column": col,
                "row_index": int(idx),
                "value": raw_val,
                "expected_range": exp_range,
                "severity": sev,
                "explanation": f"{col} value {raw_val} lies outside expected range {exp_range}"
            })
    result['anomalies'] = anomalies
except Exception:
    pass

