            valid = snap[[c1, c2]].dropna()
            if len(valid) >= 30:
                r, p = stats.pearsonr(valid[c1], valid[c2])
                if abs(r) >= 0.2:
                    result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

