try:
    anomaly_records = []
    for col in ['Amount', 'Balance After']:
        s = ob_usd[col].dropna()
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1)
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_t < lo3) | (s_t > hi3)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging suppressed'
            })
            continue
        if abs(skew) > 2:
            lo_orig = np.expm1(lo3) - shift
            hi_orig = np.expm1(hi3) - shift
        else:
