                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': float(val),
                'expected_range': f'[{lo_orig:.2f}, {hi_orig:.2f}]',
                'severity': sev,
                'explanation': f'{col} value {val:.2f} lies outside expected range [{lo_orig:.2f}, {hi_orig:.2f}]'
            })
    anomaly_records = sorted(anomaly_records, key=lambda x: {'critical':0,'high':1,'medium':2,'low':3}.get(x['severity'],4))
    result['anomalies'] = anomaly_records[:25]
