        y = monthly['Amount'].values.astype(float)
        slope, intercept, _, _, _ = stats.linregress(x, y)
        next_x = len(monthly)
        next_val = float(slope * next_x + intercept)
        next_period = str(monthly['month'].iloc[-1] + 1)
