                    result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

# ANOMALIES
try:
    anomaly_records = []
    for col in ['Amount', 'Balance After']:
        s = ob_usd[col].dropna()
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1)
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_t < lo3) | (s_t > hi3)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging suppressed'
            })
            continue
        if abs(skew) > 2:
            lo_orig = np.expm1(lo3) - shift
            hi_orig = np.expm1(hi3) - shift
        else:
            lo_orig, hi_orig = lo3, hi3
        flagged = ob_usd.loc[s_t[mask].index, col]
        for idx, val in flagged.items():
            if abs(skew) > 2:
                vt = np.log1p(val + shift)
            else:
                vt = val
            if vt > hi5 or vt < lo5:
                sev = 'critical'
            elif vt > hi4 or vt < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': float(val),
                'expected_range': f'[{lo_orig:.2f}, {hi_orig:.2f}]',
                'severity': sev,
                'explanation': f'{col} value {val:.2f} lies outside expected range [{lo_orig:.2f}, {hi_orig:.2f}]'
            })
    anomaly_records = sorted(anomaly_records, key=lambda x: {'critical':0,'high':1,'medium':2,'low':3}.get(x['severity'],4))
    result['anomalies'] = anomaly_records[:25]
except Exception:
    pass

# TREND (7d rolling on Amount net flow)
try:
    ob_usd_sorted = ob_usd.sort_values('Posting Date')
    daily = ob_usd_sorted.groupby(ob_usd_sorted['Posting Date'].dt.date)['Amount'].sum().reset_index()
    daily.columns = ['date', 'net_flow']
    daily['rolling7'] = daily['net_flow'].rolling(7).mean()
    if len(daily) >= 14:
        first_half = daily['rolling7'].dropna().iloc[:len(daily)//2].mean()
        second_half = daily['rolling7'].dropna().iloc[len(daily)//2:].mean()
        pct = float((second_half - first_half) / abs(first_half) * 100) if first_half != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': 'Amount', 'period': '7d_rolling',
            'direction': direction, 'pct_change': round(pct, 4), 'segment': None
        })
    bal_daily = ob_usd_sorted.groupby(ob_usd_sorted['Posting Date'].dt.date)['Balance After'].mean().reset_index()
    bal_daily.columns = ['date', 'avg_bal']
    bal_daily['rolling7'] = bal_daily['avg_bal'].rolling(7).mean()
    if len(bal_daily) >= 14:
        fh = bal_daily['rolling7'].dropna().iloc[:len(bal_daily)//2].mean()
        sh = bal_daily['rolling7'].dropna().iloc[len(bal_daily)//2:].mean()
        pct_b = float((sh - fh) / abs(fh) * 100) if fh != 0 else 0.0
        dir_b = 'up' if pct_b > 1 else ('down' if pct_b < -1 else 'flat')
        result['trends'].append({
            'column': 'Balance After', 'period': '7d_rolling',
            'direction': dir_b, 'pct_change': round(pct_b, 4), 'segment': None
        })
except Exception:
    pass

# FORECASTING (simple linear extrapolation on monthly net flow)
try:
    ob_usd2 = ob_usd.copy()
    ob_usd2['month'] = ob_usd2['Posting Date'].dt.to_period('M')
    monthly = ob_usd2.groupby('month')['Amount'].sum().reset_index()
    monthly = monthly.sort_values('month')
    if len(monthly) >= 3:
        x = np.arange(len(monthly))
        y = monthly['Amount'].values.astype(float)
        slope, intercept, _, _, _ = stats.linregress(x, y)
        next_x = len(monthly)
        next_val = float(slope * next_x + intercept)
        next_period = str(monthly['month'].iloc[-1] + 1)
        result['forecast_points'].append({'period': next_period, 'value': round(next_val, 2)})
        next_val2 = float(slope * (next_x + 1) + intercept)
        next_period2 = str(monthly['month'].iloc[-1] + 2)
        result['forecast_points'].append({'period': next_period2, 'value': round(next_val2, 2)})
except Exception:
    pass

# ASSUMPTIONS
result['assumptions'] = [
    "Monetary figures use on_book, USD rows only; reversed/pending/closed/reversal-entry rows excluded.",
    "Balance After treated as a level: per-period snapshot uses each account's latest on_book row.",
    "Correlations computed on one row per Account ID (latest snapshot) to avoid double-counting.",
    "Anomaly detection uses 3×IQR extreme boundary; log1p transform applied when |skew|>2.",
    "Forecast uses OLS linear trend on monthly net flow; assumes no structural breaks."
]
