    df_c[col] = pd.to_datetime(df_c[col], errors='coerce')

metrics = ['Paid to Date', 'Case Reserve', 'Incurred', 'Salvage Subrogation']
seg_cols = ['Line of Business', 'Coverage', 'Claim Status']

# EDA
try:
    eda = {}
    for col in metrics:
        s = df_c[col].dropna()
        eda[col] = {
            "mean": float(s.mean()), "std": float(s.std()),
            "min": float(s.min()), "max": float(s.max()),
            "median": float(s.median()), "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception:
    pass

# Correlations
try:
    num_cols = metrics
    corr_dict = {}
    for i, c1 in enumerate(num_cols):
        for c2 in num_cols[i+1:]:
            sub = df_c[[c1, c2]].dropna()
            if len(sub) < 10:
                continue
            r, _ = stats.pearsonr(sub[c1], sub[c2])
            if abs(r) >= 0.2:
                corr_dict[f"{c1}__{c2}"] = round(float(r), 4)
    result['correlations'] = corr_dict
except Exception:
    pass

# Segmentation
try:
    segs = []
    for seg in seg_cols:
        for metric in metrics:
            grp = df_c.groupby(seg)[metric].sum().nlargest(10)
            segs.append({
                "segment_column": seg,
                "metric_column": metric,
                "aggregation": "sum",
                "label": None,
                "results": [{"name": str(k), "value": float(v)} for k, v in grp.items()]
            })
        # claim count per segment
        cnt = df_c.groupby(seg)['Claim Number'].nunique().nlargest(10)
        segs.append({
            "segment_column": seg,
            "metric_column": "Claim Number",
            "aggregation": "count",
            "label": "claim_count",
            "results": [{"name": str(k), "value": float(v)} for k, v in cnt.items()]
        })
    result['segments'] = segs
except Exception:
    pass

# Anomalies
try:
    anomalies = []
    total = 0
    for col in metrics:
        if total >= 25:
            break
        s = df_c[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_t, hi_t = q1 - 3 * iqr, q3 + 3 * iqr
        mask = (s_t < lo_t) | (s_t > hi_t)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": "heavy-tailed distribution",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme values are natural for this distribution"
            })
            total += 1
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_t) - shift)
            hi_orig = float(np.expm1(hi_t) - shift)
        else:
            lo_orig, hi_orig = float(lo_t), float(hi_t)
        extreme_idx = s_t[mask].index
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        for idx in extreme_idx:
            if total >= 25:
                break
