            tv = s_t.loc[idx]
            if tv < lo5 or tv > hi5:
                sev = "critical"
            elif tv < lo4 or tv > hi4:
                sev = "high"
            else:
                sev = "medium"
            rng = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": val,
                "expected_range": rng, "severity": sev,
                "explanation": f"{col} value {val} lies outside expected range {rng}"
            })
            total += 1
    result['anomalies'] = anomalies
except Exception:
    pass

# Trends (MoM by Loss Date accident month — note: recent months are developing)
try:
    trends = []
    df_c['loss_ym'] = df_c['Loss Date'].dt.to_period('M')
    for metric in metrics:
        monthly = df_c.groupby('loss_ym')[metric].sum().sort_index()
        if len(monthly) >= 2:
            pct = float((monthly.iloc[-1] - monthly.iloc[-2]) / monthly.iloc[-2] * 100) if monthly.iloc[-2] != 0 else 0.0
            direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
            trends.append({
                "column": metric, "period": "MoM", "direction": direction,
                "pct_change": round(pct, 4), "segment": None
            })
    # YoY by accident year
    df_c['loss_yr'] = df_c['Loss Date'].dt.year
    for metric in metrics:
        yearly = df_c.groupby('loss_yr')[metric].sum().sort_index()
        if len(yearly) >= 2:
            pct = float((yearly.iloc[-1] - yearly.iloc[-2]) / yearly.iloc[-2] * 100) if yearly.iloc[-2] != 0 else 0.0
            direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
            trends.append({
                "column": metric, "period": "YoY", "direction": direction,
                "pct_change": round(pct, 4), "segment": None
            })
    result['trends'] = trends
except Exception:
    pass

# Forecasting: simple linear extrapolation of monthly incurred
try:
    df_c['loss_ym'] = df_c['Loss Date'].dt.to_period('M')
    monthly_inc = df_c.groupby('loss_ym')['Incurred'].sum().sort_index()
    if len(monthly_inc) >= 6:
        x = np.arange(len(monthly_inc))
        y = monthly_inc.values.astype(float)
        slope, intercept, _, _, _ = stats.linregress(x, y)
        fps = []
        last_period = monthly_inc.index[-1]
        for i in range(1, 4):
            next_p = last_period + i
            pred = float(intercept + slope * (len(monthly_inc) - 1 + i))
            fps.append({"period": str(next_p), "value": round(pred, 2)})
        result['forecast_points'] = fps
except Exception:
    pass

result['assumptions'] = [
    "Only 'counted' rows used; superseded valuations excluded.",
    "Segmentation sums use latest valuation per claim (row_kind='counted').",
    "MoM trend on accident month: recent months are still developing — interpret as development, not trend.",
    "YoY comparison names each accident year; youngest year may be immature.",
    "Forecast is a linear extrapolation of monthly incurred; treat as indicative only."
]

