# ANOMALIES
try:
    import numpy as np
    from scipy import stats as sp_stats
    anom_cols = ['Written Premium', 'Earned Premium', 'Earned Exposure', 'Claim Count', 'Incurred Losses']
    total_anomalies = 0
    for col in anom_cols:
        if total_anomalies >= 25:
            break
        s = counted[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        flagged = s_t[(s_t < lo) | (s_t > hi)]
        frac = len(flagged) / len(s_t)
        if frac > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are natural for this distribution'
            })
            continue
        # Convert boundaries back to original space
        if abs(skew) > 2:
            lo_orig = np.expm1(lo) - shift
            hi_orig = np.expm1(hi) - shift
        else:
            lo_orig, hi_orig = lo, hi
        for idx in flagged.index:
            if total_anomalies >= 25:
                break
            orig_val = float(counted.loc[idx, col])
            t_val = float(s_t.loc[idx])
            lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
            lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
            if t_val > hi5 or t_val < lo5:
                sev = 'critical'
            elif t_val > hi4 or t_val < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
            result['anomalies'].append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {orig_val} lies outside expected range {exp_range}'
            })
            total_anomalies += 1
except Exception:
    pass

