    num_df = counted[metric_cols].dropna()
    for i, c1 in enumerate(metric_cols):
        for c2 in metric_cols[i+1:]:
            r = num_df[c1].corr(num_df[c2])
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

# Segmentation
try:
    seg_cols = ['Line of Business', 'Coverage', 'Claim Status']
    agg_map = [('Paid to Date', 'sum'), ('Case Reserve', 'sum'),
               ('Incurred', 'sum'), ('Salvage Subrogation', 'sum')]
    for seg in seg_cols:
        for metric, agg in agg_map:
            grp = counted.groupby(seg)[metric].sum().nlargest(10)
            result['segments'].append({
                'segment_column': seg, 'metric_column': metric,
                'aggregation': 'sum', 'label': None,
                'results': [{'name': str(k), 'value': float(v)} for k, v in grp.items()]
            })
    # Claim count by segment
    for seg in seg_cols:
        grp = counted.groupby(seg)['Claim Number'].nunique().nlargest(10)
        result['segments'].append({
            'segment_column': seg, 'metric_column': 'Claim Number',
            'aggregation': 'count', 'label': None,
            'results': [{'name': str(k), 'value': float(v)} for k, v in grp.items()]
        })
    # Severity by Line of Business
    sev = counted.groupby('Line of Business').apply(
        lambda x: x['Incurred'].sum() / x['Claim Number'].nunique()
    ).nlargest(10)
    result['segments'].append({
        'segment_column': 'Line of Business', 'metric_column': 'Incurred',
        'aggregation': 'ratio', 'label': 'severity_incurred_per_claim',
        'results': [{'name': str(k), 'value': float(v)} for k, v in sev.items()]
    })
    # Cat vs non-cat incurred ratio
    counted['_is_cat'] = counted['Cat Event'].notna() & (counted['Cat Event'] != '')
    cat_grp = counted.groupby('_is_cat')['Incurred'].sum()
    total_inc = cat_grp.sum()
    result['segments'].append({
        'segment_column': 'Cat Event', 'metric_column': 'Incurred',
        'aggregation': 'ratio', 'label': 'cat_incurred_share',
        'results': [{'name': 'cat' if k else 'non_cat', 'value': float(v / total_inc)} for k, v in cat_grp.items()]
    })
except Exception:
    pass

# Anomalies
try:
    anomaly_records = []
    for col in metric_cols:
        s = counted[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        flagged = s_t[(s_t < lo) | (s_t > hi)]
        if len(flagged) / len(s_t) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are natural, not anomalies'
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo) - shift)
            hi_orig = float(np.expm1(hi) - shift)
        else:
            lo_orig, hi_orig = float(lo), float(hi)
        exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
        for idx in flagged.index:
            orig_val = float(counted.loc[idx, col])
            s_val = float(s_t[idx])
            lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
            lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
            if s_val > hi5 or s_val < lo5:
                sev = 'critical'
            elif s_val > hi4 or s_val < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {orig_val:.2f} lies outside expected range {exp_range}'
            })
            if len(anomaly_records) >= 25:
                break
        if len(anomaly_records) >= 25:
            break
    result['anomalies'] = anomaly_records
except Exception:
    pass

# Trends (Loss Date based, accident year — no MoM on accident periods per domain rules)
try:
    counted['_loss_year'] = counted['Loss Date'].dt.year
    ay_inc = counted.groupby('_loss_year')['Incurred'].sum()
    ay_paid = counted.groupby('_loss_year')['Paid to Date'].sum()
    ay_res = counted.groupby('_loss_year')['Case Reserve'].sum()
    years = sorted(ay_inc.index.tolist())
    for metric_s, ay_s in [('Incurred', ay_inc), ('Paid to Date', ay_paid), ('Case Reserve', ay_res)]:
        if len(years) >= 2:
            vals = [ay_s.get(y, 0) for y in years]
            pct = float((vals[-1] - vals[-2]) / vals[-2] * 100) if vals[-2] != 0 else 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': metric_s, 'period': 'YoY', 'direction': direction,
                'pct_change': round(pct, 2), 'segment': None
            })
    # Report Date MoM for claim counts (not accident period)
    counted['_report_ym'] = counted['Report Date'].dt.to_period('M')
    monthly_claims = counted.groupby('_report_ym')['Claim Number'].nunique()
    if len(monthly_claims) >= 2:
        last2 = monthly_claims.iloc[-2:]
        pct_c = float((last2.iloc[-1] - last2.iloc[-2]) / last2.iloc[-2] * 100) if last2.iloc[-2] != 0 else 0.0
        dir_c = 'up' if pct_c > 1 else ('down' if pct_c < -1 else 'flat')
        result['trends'].append({
            'column': 'Claim Number', 'period': 'MoM', 'direction': dir_c,
            'pct_change': round(pct_c, 2), 'segment': 'report_date_based'
        })
except Exception:
    pass

# Forecasting (simple linear extrapolation on accident year incurred)
try:
    counted['_loss_year'] = counted['Loss Date'].dt.year
    ay_inc2 = counted.groupby('_loss_year')['Incurred'].sum().reset_index()
    ay_inc2.columns = ['year', 'incurred']
    if len(ay_inc2) >= 3:
        x = ay_inc2['year'].values.astype(float)
        y = ay_inc2['incurred'].values.astype(float)
        slope, intercept, _, _, _ = stats.linregress(x, y)
        next_year = int(x.max()) + 1
        forecast_val = float(slope * next_year + intercept)
        result['forecast_points'].append({'period': str(next_year), 'value': round(forecast_val, 2)})
except Exception:
    pass

result['assumptions'] = [
    "Only 'counted' rows used: latest valuation per claim per domain rules.",
    "Accident-year trends only; MoM on accident periods suppressed (immature years still developing).",
    "Severity = total Incurred / distinct Claim Numbers within each segment.",
    "Forecasting uses OLS linear regression on accident-year incurred totals; extrapolation uncertainty is high.",
    "Anomaly detection uses log1p transform for skewed columns; heavy-tailed columns noted, not flagged."
]
